    37	    @BeforeAll
    38	    static void startTransLog() throws IOException {
    39	        translog = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
    40	        translog.createContext("/v2/quote", exchange -> {
    41	            byte[] body = translogBody.getBytes(StandardCharsets.UTF_8);
    42	            exchange.sendResponseHeaders(translogStatus, body.length);
    43	            exchange.getResponseBody().write(body);
    44	            exchange.close();
    45	        });
    46	        translog.start();
    47	    }
    48	
    49	    @AfterAll
    50	    static void stopTransLog() {
    51	        translog.stop(0);
    52	    }
    53	
    54	    @DynamicPropertySource
    55	    static void properties(DynamicPropertyRegistry registry) throws IOException {
    56	        // o servidor precisa existir antes do contexto
    57	        if (translog == null) {
    58	            startTransLog();
    59	        }
    60	        registry.add("translog.url", () -> "http://127.0.0.1:" + translog.getAddress().getPort());
    61	        registry.add("spring.datasource.url", () -> "jdbc:h2:mem:pedidos;MODE=PostgreSQL;DB_CLOSE_DELAY=-1");
    62	        registry.add("spring.datasource.username", () -> "sa");
    63	        registry.add("spring.datasource.password", () -> "");
    64	    }
