    80	    private static String purchase(String cpf, String items, String shipping, String coupon, String payment,
    81	                                   int installments, String tier, String region) {
    82	        return """
    83	                {"customer":{"cpf":"%s","email":"a@b.com"},"items":[%s],"zipCode":"01310100","region":"%s",
    84	                 "shippingMethod":"%s",%s"paymentMethod":"%s","installments":%d,"clubTier":"%s"}
    85	                """.formatted(cpf, items, region, shipping, coupon == null ? "" : "\"coupon\":\"" + coupon + "\",",
    86	                payment, installments, tier);
    87	    }
