   104	    private void expectSummary(ResultActions r, String subtotal, String coupon, String shipping, int days,
   105	                               String insurance, String adjustment, String total, int n, String installment,
   106	                               String credit, boolean gift) throws Exception {
   107	        r.andExpect(status().isOk())
   108	                .andExpect(jsonPath("$.productsSubtotal").value(Double.parseDouble(subtotal)))
   109	                .andExpect(jsonPath("$.couponDiscount").value(Double.parseDouble(coupon)))
   110	                .andExpect(jsonPath("$.shippingCost").value(Double.parseDouble(shipping)))
   111	                .andExpect(jsonPath("$.deliveryDays").value(days))
   112	                .andExpect(jsonPath("$.insurance").value(Double.parseDouble(insurance)))
   113	                .andExpect(jsonPath("$.paymentAdjustment").value(Double.parseDouble(adjustment)))
   114	                .andExpect(jsonPath("$.finalTotal").value(Double.parseDouble(total)))
   115	                .andExpect(jsonPath("$.installments").value(n))
   116	                .andExpect(jsonPath("$.installmentAmount").value(Double.parseDouble(installment)))
   117	                .andExpect(jsonPath("$.nextPurchaseCredit").value(Double.parseDouble(credit)))
   118	                .andExpect(jsonPath("$.gift").value(gift));
   119	    }
