   234	    @Test
   235	    void paymentLifecycleIsIdempotentAndStockNeverGoesNegative() throws Exception {
   236	        String cpf = newCpf();
   237	        String body = purchase(cpf, "{\"sku\":\"MOC-001\",\"quantity\":1}", "STORE_PICKUP", null, "PIX", 1, "SILVER",
   238	                "SOUTH");
   239	        String first = register(body);
   240	        String second = register(body);
   241	        String paidAt = java.time.Instant.now().toString();
   242	        String notice = "{\"transactionId\":\"TX-A\",\"paidAt\":\"" + paidAt + "\"}";
   243	
   244	        send("/orders/" + first + "/payment", notice).andExpect(status().isOk())
   245	                .andExpect(jsonPath("$.status").value("PAID"));
   246	        send("/orders/" + first + "/payment", notice).andExpect(status().isOk())
   247	                .andExpect(jsonPath("$.status").value("PAID"));
   248	        send("/orders/" + first + "/payment", "{\"transactionId\":\"TX-B\",\"paidAt\":\"" + paidAt + "\"}")
   249	                .andExpect(status().isConflict()).andExpect(jsonPath("$.error").value("OPERATION_NOT_ALLOWED"));
   250	        mvc.perform(get("/products/MOC-001")).andExpect(jsonPath("$.stock").value(0));
   251	        mvc.perform(get("/customers/" + cpf)).andExpect(jsonPath("$.creditBalance").value(3.2));
   252	
   253	        // última peça já foi paga: o segundo pedido é recusado e cancelado, e a recusa se repete
   254	        String lost = "{\"transactionId\":\"TX-C\",\"paidAt\":\"" + paidAt + "\"}";
   255	        send("/orders/" + second + "/payment", lost).andExpect(status().isConflict())
   256	                .andExpect(jsonPath("$.error").value("INSUFFICIENT_STOCK"));
   257	        send("/orders/" + second + "/payment", lost).andExpect(status().isConflict())
   258	                .andExpect(jsonPath("$.error").value("INSUFFICIENT_STOCK"));
   259	        mvc.perform(get("/orders/" + second)).andExpect(jsonPath("$.status").value("CANCELLED"));
   260	
   261	        // cancelar o pedido pago devolve estoque e tira o crédito
   262	        send("/orders/" + first + "/cancellation", "").andExpect(status().isOk())
   263	                .andExpect(jsonPath("$.status").value("CANCELLED"));
   264	        mvc.perform(get("/products/MOC-001")).andExpect(jsonPath("$.stock").value(1));
   265	        mvc.perform(get("/customers/" + cpf)).andExpect(jsonPath("$.creditBalance").value(0.0));
   266	        mvc.perform(get("/customers/" + cpf + "/notifications"))
   267	                .andExpect(jsonPath("$.length()").value(3))
   268	                .andExpect(jsonPath("$[0].type").value("PAYMENT_APPROVED"))
   269	                .andExpect(jsonPath("$[0].status").value("NEW"))
   270	                .andExpect(jsonPath("$[2].type").value("ORDER_CANCELLED"));
   271	    }
