   273	    @Test
   274	    void expirationAndShipping() throws Exception {
   275	        String body = purchase(newCpf(), "{\"sku\":\"MEI-001\",\"quantity\":1}", "STORE_PICKUP", null, "PIX", 1,
   276	                "BRONZE", "SOUTH");
   277	        String id = register(body);
   278	        String createdAt = mapper.readTree(mvc.perform(get("/orders/" + id)).andReturn().getResponse()
   279	                .getContentAsString()).get("createdAt").asString();
   280	        java.time.Instant created = java.time.Instant.parse(createdAt);
   281	
   282	        send("/orders/" + id + "/shipment", "{\"trackingCode\":\"BR1\"}").andExpect(status().isConflict());
   283	        send("/orders/" + id + "/payment", "{\"transactionId\":\"T\",\"paidAt\":\""
   284	                + created.plusSeconds(48 * 3600 + 1) + "\"}").andExpect(status().isConflict())
   285	                .andExpect(jsonPath("$.error").value("ORDER_EXPIRED"));
   286	        mvc.perform(get("/orders/" + id)).andExpect(jsonPath("$.status").value("CANCELLED"));
   287	
   288	        String ok = register(body);
   289	        created = java.time.Instant.parse(mapper.readTree(mvc.perform(get("/orders/" + ok)).andReturn().getResponse()
   290	                .getContentAsString()).get("createdAt").asString());
   291	        send("/orders/" + ok + "/payment", "{\"transactionId\":\"T\",\"paidAt\":\"" + created.plusSeconds(48 * 3600)
   292	                + "\"}").andExpect(status().isOk());
   293	        send("/orders/" + ok + "/shipment", "{}").andExpect(status().isUnprocessableEntity());
   294	        send("/orders/" + ok + "/shipment", "{\"trackingCode\":\"BR1\"}").andExpect(status().isOk())
   295	                .andExpect(jsonPath("$.trackingCode").value("BR1"));
   296	        send("/orders/" + ok + "/cancellation", "").andExpect(status().isConflict());
   297	        send("/orders/" + ok + "/delivery", "").andExpect(status().isOk())
   298	                .andExpect(jsonPath("$.status").value("DELIVERED"));
   299	        send("/orders/nope/delivery", "").andExpect(status().isNotFound())
   300	                .andExpect(jsonPath("$.error").value("ORDER_NOT_FOUND"));
   301	    }
