   304	    void notificationsCanBeReadAndUnknownResourcesAre404() throws Exception {
   305	        String cpf = newCpf();
   306	        String id = register(purchase(cpf, "{\"sku\":\"MEI-001\",\"quantity\":1}", "STORE_PICKUP", null, "PIX", 1,
