   309	        String json = mvc.perform(get("/customers/" + cpf + "/notifications")).andReturn().getResponse()
   310	                .getContentAsString();
   311	        String nid = mapper.readTree(json).get(0).get("id").asString();
   312	        send("/notifications/" + nid + "/read", "").andExpect(jsonPath("$.status").value("READ"));
   313	        send("/notifications/" + nid + "/read", "").andExpect(jsonPath("$.status").value("READ"));
   314	        send("/notifications/zzz/read", "").andExpect(status().isNotFound())
   315	                .andExpect(jsonPath("$.error").value("NOTIFICATION_NOT_FOUND"));
   316	        mvc.perform(get("/customers/00000000000/notifications")).andExpect(status().isNotFound())
   317	                .andExpect(jsonPath("$.error").value("CUSTOMER_NOT_FOUND"));
   318	        mvc.perform(get("/products/NOPE")).andExpect(jsonPath("$.error").value("PRODUCT_NOT_FOUND"));
